import{_ as t,c as e,o as a,a3 as d}from"./chunks/framework.C5U8cnJv.js";const o="/xhh-blog/assets/image.DCHDd3mP.png",r="/xhh-blog/assets/image-18.OMZq3UU-.png",l="/xhh-blog/assets/image-19.CgXwqR3M.png",s="/xhh-blog/assets/image-20.B81fPtwG.png",f=JSON.parse('{"title":"Qoder","description":"","frontmatter":{},"headers":[],"relativePath":"ai/qoder.md","filePath":"ai/qoder.md"}'),i={name:"ai/qoder.md"},c=d('<h1 id="qoder" tabindex="-1"><a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">Qoder</a> <a class="header-anchor" href="#qoder" aria-label="Permalink to &quot;[Qoder](https://qoder.com.cn/)&quot;">​</a></h1><p>Qoder CN（原通义灵码）是阿里云 IDE AI 编程助手，原生适配 VSCode。支持仓库级代码理解、Agent 自动多文件修改、行间代码补全、代码审查，内置通义 Qwen 系列模型。</p><p>VSCode Qoder CN 插件：</p><p><img src="'+o+'" alt="alt text"></p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>路径</th><th>作用域</th></tr></thead><tbody><tr><td>项目级 Skills</td><td>项目根目录/.lingma/skills</td><td>仅对当前项目生效</td></tr><tr><td>全局 Skills</td><td>用户主目录/.lingma/skills</td><td>对所有项目生效</td></tr></tbody></table><p>输入 <code>/技能名称</code> 调用</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>Qoder CN 聊天面板 =&gt; 右上角用户 =&gt; Settings =&gt; MCP Servers =&gt; Add by JSON:</p><p><img src="'+r+'" alt="alt text"></p><p>这里使用的是 MCP 协议的通用 STDIO 配置。</p><table tabindex="0"><thead><tr><th>对比</th><th>stdio</th><th>SSE/HTTP</th></tr></thead><tbody><tr><td>通信含义</td><td>本地进程管道通信，Qoder 拉起 Node 子进程，通过控制台输入输出传递MCP消息</td><td>HTTP SSE长流网络通信，先GET建立长连接，后续指令POST交互</td></tr><tr><td>Figma官方支持</td><td>❌ 官方无stdio版本，可使用第三方社区包<code>figma-mcp</code>、 <a href="https://github.com/GLips/Figma-Context-MCP" target="_blank" rel="noreferrer">figma-developer-mcp</a></td><td>✅ Figma官方MCP原生基于SSE</td></tr><tr><td>配置写法</td><td><code>command</code> + <code>args</code> + <code>env</code></td><td><code>type:http</code> + <code>url</code></td></tr></tbody></table><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>方案1：界面创建</p><p><img src="'+l+'" alt="alt text"></p><ul><li>规则类型（3 种） <ul><li>Manual（手动引入）：聊天框输入 <code>@vue-standard</code> 才启用</li><li>Model Decision：AI 自动判断场景触发（比如写代码时自动生效）</li><li>Specific Files：指定文件后缀自动生效，例如<code>*.vue,*.js</code></li><li>Always：<strong>当前项目下，所有对话/提问，强制永久加载这条规则</strong>，无需手动 @，慎用</li></ul></li></ul><p><img src="'+s+'" alt="alt text"></p><p>方案2：手动新建文件</p><p>项目根目录新建文件夹 .lingma/rules/，在 rules 文件夹新建 <code>vue-standard.md</code> 文件</p>',19),n=[c];function h(p,m,g,_,u,b){return a(),e("div",null,n)}const P=t(i,[["render",h]]);export{f as __pageData,P as default};
